	private static void assertConcurrentAutoFlushBehavior(boolean nonblockingContender) throws Exception {
		RecordingStreamingSource backing = new RecordingStreamingSource();
		SailSourceBranch branch = new SailSourceBranch(backing, new DynamicModelFactory(), true);
		Statement queued = statement(nonblockingContender
				? "concurrent-auto-flush-during-admission"
				: "explicit-prepare-during-auto-flush-admission");
		SailDataset initialObserver = branch.dataset(IsolationLevels.SNAPSHOT_READ);
		add(branch, queued);
		try (SailDataset bufferedView = branch.dataset(IsolationLevels.NONE)) {
			assertThat(readAll(bufferedView.getStatements(null, null, null)))
					.as("the real row is published to the branch while the original observer remains open")
					.containsExactly(queued);
		}
		assertThat(backing.committed).as("the observer holds the real published row in the branch")
				.doesNotContain(queued);
		assertThat(branch.isChanged()).as("the row is published to the branch and awaits backing application")
				.isTrue();

		CountDownLatch admissionReached = new CountDownLatch(1);
		CountDownLatch releaseAdmission = new CountDownLatch(1);
		AtomicReference<StatementInput> admittedInput = new AtomicReference<>();
		AtomicInteger rowsAtAdmission = new AtomicInteger();
		AtomicBoolean ordinaryGuardHeldAtAdmission = new AtomicBoolean(true);
		backing.onEstimate = input -> {
			if (backing.estimateCalls.get() == 1) {
				admittedInput.set(input);
				ordinaryGuardHeldAtAdmission.set(SailModelCleanup.holdsOrdinaryGuard());
				try (CloseableIteration<Statement> cursor = input.openCursor()) {
					while (cursor.hasNext()) {
						cursor.next();
						rowsAtAdmission.incrementAndGet();
					}
				}
				admissionReached.countDown();
				await(releaseAdmission, "first autoFlush admission release");
			}
		};

		ExecutorService executor = Executors.newFixedThreadPool(2);
		Future<?> firstAutoFlush = executor.submit(initialObserver::close);
		Future<?> contender = null;
		Throwable firstFailure = null;
		Throwable contenderFailure = null;
		boolean contenderCompletedBeforeRelease = false;
		boolean contenderReturnedNormally = false;
		boolean firstStillPausedAtContenderReturn = false;
		boolean pendingAtContenderReturn = false;
		boolean appliedAtContenderReturn = false;
		boolean inputStillOpenAtContenderReturn = false;
		int livePreparationsAtContenderReturn = -1;
		try {
			await(admissionReached, "first autoFlush numeric admission callback");
			contender = executor.submit(() -> {
				if (nonblockingContender) {
					branch.autoFlush();
				} else {
					branch.prepare();
				}
			});
			try {
				contender.get(2, TimeUnit.SECONDS);
				contenderCompletedBeforeRelease = true;
				contenderReturnedNormally = true;
			} catch (java.util.concurrent.TimeoutException stillRunning) {
				// Release the first admission before reporting that its contender failed to return promptly.
			} catch (java.util.concurrent.ExecutionException failure) {
				contenderCompletedBeforeRelease = true;
				contenderFailure = failure.getCause();
			}
			if (contenderCompletedBeforeRelease) {
				firstStillPausedAtContenderReturn = !firstAutoFlush.isDone();
				pendingAtContenderReturn = branch.isChanged();
				appliedAtContenderReturn = backing.committed.contains(queued);
				livePreparationsAtContenderReturn = backing.liveSinkPreparations.get();
				StatementInput input = admittedInput.get();
				if (input != null) {
					try (CloseableIteration<Statement> cursor = input.openCursor()) {
						inputStillOpenAtContenderReturn = cursor.hasNext() && queued.equals(cursor.next())
								&& !cursor.hasNext();
					}
				}
			}
		} finally {
			releaseAdmission.countDown();
			try {
				firstAutoFlush.get(5, TimeUnit.SECONDS);
			} catch (java.util.concurrent.ExecutionException failure) {
				firstFailure = failure.getCause();
			} catch (java.util.concurrent.TimeoutException failure) {
				firstFailure = failure;
			}
			if (contender != null) {
				try {
					contender.get(5, TimeUnit.SECONDS);
				} catch (java.util.concurrent.ExecutionException failure) {
					if (contenderFailure == null) {
						contenderFailure = failure.getCause();
					}
				} catch (java.util.concurrent.TimeoutException failure) {
					if (contenderFailure == null) {
						contenderFailure = failure;
					}
				}
			}
			try {
				branch.close();
			} catch (Throwable failure) {
				if (firstFailure == null) {
					firstFailure = failure;
				} else {
					firstFailure.addSuppressed(failure);
				}
			}
			executor.shutdownNow();
			if (!executor.awaitTermination(5, TimeUnit.SECONDS) && firstFailure == null) {
				firstFailure = new AssertionError("concurrent preflight executor did not terminate");
			}
		}

		assertThat(backing.estimateCalls).as("the first autoFlush reached numeric admission").hasValue(1);
		assertThat(admittedInput.get()).as("the first admission retained its actual input").isNotNull();
		assertThat(rowsAtAdmission).as("the admitted input contained the real buffered row").hasValue(1);
		assertThat(ordinaryGuardHeldAtAdmission)
				.as("numeric admission runs without holding an ordinary branch guard")
				.isFalse();
		assertThat(contenderCompletedBeforeRelease)
				.as("the contender returns while the first admission remains paused")
				.isTrue();
		assertThat(firstStillPausedAtContenderReturn)
				.as("the first autoFlush is still inside its admission callback when the contender returns")
				.isTrue();
		assertThat(pendingAtContenderReturn).as("the contender does not dispose the shared input").isTrue();
		assertThat(appliedAtContenderReturn).as("neither contender applies the row during admission").isFalse();
		assertThat(inputStillOpenAtContenderReturn)
				.as("the first admission input stays open until its owner completes")
				.isTrue();
		assertThat(livePreparationsAtContenderReturn).as("no backing preparation started before admission returns")
				.isZero();
		assertThat(firstFailure).as("the first autoFlush succeeds after its admission is released").isNull();
		if (nonblockingContender) {
			assertThat(contenderReturnedNormally)
					.as("a concurrent opportunistic autoFlush skips an already-running admission")
					.withFailMessage("contending autoFlush failure=%s, admissionRows=%s, ordinaryGuardHeld=%s, "
							+ "firstPaused=%s, pending=%s, applied=%s, inputOpen=%s",
							contenderFailure, rowsAtAdmission, ordinaryGuardHeldAtAdmission,
							firstStillPausedAtContenderReturn, pendingAtContenderReturn,
							appliedAtContenderReturn, inputStillOpenAtContenderReturn)
					.isTrue();
			assertThat(contenderFailure).as("a concurrent opportunistic autoFlush does not fail").isNull();
		} else {
			assertThat(contenderFailure).as("explicit preparation retains the typed concurrency conflict")
					.isInstanceOf(SailConflictException.class);
		}
		assertThat(backing.estimatedRows).hasValue(1);
		assertThat(backing.committed).containsExactly(queued);
		assertThat(backing.approvalCount(queued)).as("the shared row is applied exactly once").hasValue(1);
		assertThat(backing.liveSinkPreparations).hasValue(0);
		assertThat(backing.liveWriteReservations).hasValue(0);
		assertThat(backing.retainedOwnerCount).hasValue(backing.retainedOwnerCloses.get());
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void concurrentPrepareCannotReuseCarrierWhileAutoFlushRetiresIt() throws Exception {
		RecordingStreamingSource backing = new RecordingStreamingSource();
		SailSourceBranch branch = new SailSourceBranch(new LegacyPreflightSource(backing), new DynamicModelFactory(),
				true);
		Statement queued = statement("prepare-during-carrier-retirement");
		SailDataset initialObserver = branch.dataset(IsolationLevels.SNAPSHOT_READ);
		try (SailSink sink = branch.sink(IsolationLevels.NONE)) {
			sink.approve(queued);
			sink.flush();
		}
		AtomicReference<SailDataset> replacementObserver = new AtomicReference<>();
		AtomicBoolean prepareHookActivated = new AtomicBoolean();
		AtomicBoolean releaseHookArmed = new AtomicBoolean(true);
		CountDownLatch releaseEntered = new CountDownLatch(1);
		CountDownLatch continueRelease = new CountDownLatch(1);
		AtomicReference<Throwable> concurrentPrepareFailure = new AtomicReference<>();
		AtomicBoolean concurrentPrepareReturned = new AtomicBoolean();
		AtomicInteger rawPreparationsAtReleaseBarrier = new AtomicInteger(-1);
		AtomicInteger rawPreparationsAfterRelease = new AtomicInteger(-1);
		AtomicBoolean pendingAtSkip = new AtomicBoolean();
		AtomicBoolean publishedAtSkip = new AtomicBoolean();
		ExecutorService executor = Executors.newSingleThreadExecutor();

		backing.onSinkPrepare = () -> {
			if (prepareHookActivated.compareAndSet(false, true)) {
				replacementObserver.set(branch.dataset(IsolationLevels.SNAPSHOT_READ));
			}
		};
		backing.onSinkPreparationRelease = () -> {
			if (releaseHookArmed.compareAndSet(true, false)) {
				releaseEntered.countDown();
				await(continueRelease, "retiring carrier release");
			}
		};

		Future<?> closeInitialObserver = executor.submit(initialObserver::close);
		try {
			await(releaseEntered, "autoFlush raw carrier release barrier");
			rawPreparationsAtReleaseBarrier.set(backing.liveSinkPreparations.get());
			try {
				branch.prepare();
				concurrentPrepareReturned.set(true);
			} catch (Throwable failure) {
				concurrentPrepareFailure.set(failure);
			}
		} finally {
			continueRelease.countDown();
			closeInitialObserver.get(5, TimeUnit.SECONDS);
			if (concurrentPrepareReturned.get()) {
				rawPreparationsAfterRelease.set(backing.liveSinkPreparations.get());
			}
			pendingAtSkip.set(branch.isChanged());
			publishedAtSkip.set(backing.committed.contains(queued));
			SailDataset observer = replacementObserver.get();
			if (observer != null) {
				observer.close();
			}
			branch.close();
			executor.shutdownNow();
			executor.awaitTermination(5, TimeUnit.SECONDS);
		}

		assertThat(prepareHookActivated).as("autoFlush entered the raw backing prepare").isTrue();
		assertThat(replacementObserver.get()).as("the replacement reader was opened by the real prepare hook")
				.isNotNull();
		assertThat(releaseEntered.getCount()).as("autoFlush reached physical carrier release").isZero();
		assertThat(rawPreparationsAtReleaseBarrier)
				.as("the raw carrier remains prepared while its release callback is paused")
				.hasValue(1);
		if (concurrentPrepareReturned.get()) {
			assertThat(rawPreparationsAfterRelease)
					.as("a successful concurrent preparation must retain the raw carrier after old release")
					.hasValue(1);
		} else {
			assertThat(concurrentPrepareFailure.get()).as("a rejected concurrent prepare must report a conflict")
					.isInstanceOf(SailConflictException.class);
		}
		assertThat(pendingAtSkip).as("the competing preparation does not discard the pending row").isTrue();
		assertThat(publishedAtSkip).as("the competing preparation does not publish the pending row").isFalse();
		assertThat(backing.liveSinkPreparations).hasValue(0);
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void freezingDuringAutoFlushPreparationRetainsCarrierUntilBatchCancellation() throws Exception {
		RecordingStreamingSource backing = new RecordingStreamingSource();
		SailSourceBranch branch = new SailSourceBranch(backing, new DynamicModelFactory(), true);
		Statement queued = statement("freeze-during-auto-flush-preparation");
		SailSource.FlushBatch emptyBatch = branch.freezeForFlush();
		add(branch, queued);
		emptyBatch.close();
		AtomicReference<SailSource.FlushBatch> frozenBatch = new AtomicReference<>();
		AtomicBoolean hookActivated = new AtomicBoolean();
		backing.onSinkPrepare = () -> {
			if (hookActivated.compareAndSet(false, true)) {
				frozenBatch.set(branch.freezeForFlush());
			}
		};

		try {
			branch.autoFlush();

			assertThat(hookActivated).as("the raw carrier entered backing preparation").isTrue();
			assertThat(frozenBatch.get()).as("the in-flight carrier was adopted by the frozen batch").isNotNull();
			assertThat(backing.liveSinkPreparations)
					.as("the frozen batch retains its adopted carrier until release")
					.hasValue(1);
			assertThat(branch.isChanged()).as("freezing during preparation retains the buffered row").isTrue();
			assertThat(backing.committed).as("autoFlush does not publish after the batch wins").doesNotContain(queued);

			frozenBatch.get().close();
			assertThat(backing.liveSinkPreparations).as("batch cancellation releases its adopted carrier").hasValue(0);
			assertThat(branch.isChanged()).as("batch cancellation preserves the pending row").isTrue();
			assertThat(backing.committed).as("batch cancellation does not publish the row").doesNotContain(queued);

			branch.flush();
			assertThat(backing.committed).containsExactly(queued);
		} finally {
			SailSource.FlushBatch batch = frozenBatch.get();
			if (batch != null) {
				batch.close();
			}
			branch.close();
		}
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void autoFlushReleasesNewCarrierWhenSecondBranchLockIsBusy() throws Exception {
		RecordingStreamingSource backing = new RecordingStreamingSource();
		SailSourceBranch branch = new SailSourceBranch(new LegacyPreflightSource(backing), new DynamicModelFactory(),
				true);
		Statement queued = statement("busy-second-auto-flush-snapshot");
		SailDataset initialObserver = branch.dataset(IsolationLevels.SNAPSHOT_READ);
		try (SailSink sink = branch.sink(IsolationLevels.NONE)) {
			sink.approve(queued);
			sink.flush();
		}
		AtomicReference<SailDataset> replacementObserver = new AtomicReference<>();
		AtomicReference<Thread> autoFlushThread = new AtomicReference<>();
		AtomicReference<Future<?>> holderFuture = new AtomicReference<>();
		AtomicReference<Throwable> holderFailure = new AtomicReference<>();
		AtomicBoolean autoPrepareHook = new AtomicBoolean();
		AtomicBoolean holderPrepareReturned = new AtomicBoolean();
		CountDownLatch holderPrepared = new CountDownLatch(1);
		CountDownLatch releaseHolder = new CountDownLatch(1);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		AtomicBoolean autoFlushReturnedBeforeHolderRelease = new AtomicBoolean();
		AtomicInteger rawPreparationsAtSkip = new AtomicInteger(-1);
		AtomicBoolean pendingAtSkip = new AtomicBoolean();
		AtomicBoolean publishedAtSkip = new AtomicBoolean();
		backing.onSinkPrepare = () -> {
			Thread current = Thread.currentThread();
			if (current == autoFlushThread.get() && autoPrepareHook.compareAndSet(false, true)) {
				replacementObserver.set(branch.dataset(IsolationLevels.SNAPSHOT_READ));
				holderFuture.set(executor.submit(() -> {
					try (SailSink holder = branch.sink(IsolationLevels.SERIALIZABLE)) {
						holder.prepare();
						holderPrepareReturned.set(true);
						holderPrepared.countDown();
						await(releaseHolder, "foreign prepared sink release");
					} catch (Throwable failure) {
						holderFailure.set(failure);
						holderPrepared.countDown();
					}
				}));
				await(holderPrepared, "foreign prepared sink holding the branch guard");
			}
		};

		Future<?> autoFlushFuture = executor.submit(() -> {
			autoFlushThread.set(Thread.currentThread());
			initialObserver.close();
		});
		try {
			await(holderPrepared, "foreign prepared sink callback");
			if (holderFailure.get() == null) {
				try {
					autoFlushFuture.get(2, TimeUnit.SECONDS);
					autoFlushReturnedBeforeHolderRelease.set(true);
				} catch (java.util.concurrent.TimeoutException blocked) {
					// Release the foreign prepared sink before asserting the nonblocking requirement.
				}
				if (autoFlushReturnedBeforeHolderRelease.get()) {
					rawPreparationsAtSkip.set(backing.liveSinkPreparations.get());
				}
			}
		} finally {
			releaseHolder.countDown();
			autoFlushFuture.get(5, TimeUnit.SECONDS);
			Future<?> holder = holderFuture.get();
			if (holder != null) {
				holder.get(5, TimeUnit.SECONDS);
			}
			pendingAtSkip.set(branch.isChanged());
			publishedAtSkip.set(backing.committed.contains(queued));
			SailDataset replacement = replacementObserver.get();
			if (replacement != null) {
				replacement.close();
			}
			executor.shutdownNow();
			executor.awaitTermination(5, TimeUnit.SECONDS);
			branch.close();
		}

		assertThat(autoPrepareHook).as("autoFlush entered backing preparation").isTrue();
		assertThat(holderPrepareReturned).as("a public prepared sink acquired the branch during raw preparation")
				.isTrue();
		assertThat(holderFailure.get()).as("the foreign sink preparation completed").isNull();
		assertThat(autoFlushReturnedBeforeHolderRelease)
				.as("autoFlush must skip a busy second snapshot acquisition")
				.isTrue();
		assertThat(rawPreparationsAtSkip).as("the skipped autoFlush releases its raw carrier").hasValue(0);
		assertThat(pendingAtSkip).as("a busy skip keeps the queued row pending").isTrue();
		assertThat(publishedAtSkip).as("a busy skip does not publish the queued row").isFalse();
		assertThat(backing.liveSinkPreparations).hasValue(0);
		assertThat(backing.committed).containsExactly(queued);
	}

	@Test
	@Timeout(value = 10, unit = TimeUnit.SECONDS)
	void autoFlushReturnsWhileAncestorPreparedSinkStillOwnsBranchGuard() throws Exception {
		RecordingStreamingSource backing = new RecordingStreamingSource();
		SailSourceBranch parent = branch(backing);
		SailSourceBranch child = new SailSourceBranch(parent, new DynamicModelFactory(), true);
		SailSource.FlushBatch emptyBatch = child.freezeForFlush();
		add(child, statement("later-child-generation"));
		emptyBatch.close();

		ExecutorService executor = Executors.newFixedThreadPool(2);
		CountDownLatch parentPrepared = new CountDownLatch(1);
		CountDownLatch releaseParent = new CountDownLatch(1);
		AtomicBoolean returnedBeforeRelease = new AtomicBoolean();
		Future<?> parentTask = executor.submit(() -> {
			try (SailSink sink = parent.sink(IsolationLevels.SERIALIZABLE)) {
				sink.prepare();
				parentPrepared.countDown();
				await(releaseParent, "parent preparation release");
			}
		});
		Future<?> autoFlushTask = null;
		try {
			await(parentPrepared, "ancestor prepared sink");
			autoFlushTask = executor.submit(child::autoFlush);
			try {
				autoFlushTask.get(2, TimeUnit.SECONDS);
				returnedBeforeRelease.set(true);
			} catch (java.util.concurrent.TimeoutException blockedByAncestor) {
				// Release the held sink in finally before reporting the nonblocking contract failure.
			}
		} finally {
			releaseParent.countDown();
			parentTask.get(5, TimeUnit.SECONDS);
			if (autoFlushTask != null) {
				autoFlushTask.get(5, TimeUnit.SECONDS);
			}
			child.close();
			parent.close();
			executor.shutdownNow();
			executor.awaitTermination(5, TimeUnit.SECONDS);
		}

		assertThat(returnedBeforeRelease).as("child autoFlush should not wait for an ancestor's prepared sink")
				.isTrue();
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void autoFlushDoesNotWaitForAncestorOwnerResolution() throws Exception {
		RecordingStreamingSource terminal = new RecordingStreamingSource();
		terminal.nullOwnerReturnsNull = true;
		SailSourceBranch parent = branch(terminal);
		SailSourceBranch child = new SailSourceBranch(parent, new DynamicModelFactory(), true);
		Statement queued = statement("auto-flush-owner-resolution");
		SailSource.FlushBatch emptyBatch = child.freezeForFlush();
		add(child, queued);
		emptyBatch.close();

		AtomicReference<Thread> autoFlushThread = new AtomicReference<>();
		AtomicInteger autoFlushOwnerQueries = new AtomicInteger();
		AtomicInteger hookQuery = new AtomicInteger();
		AtomicBoolean hookActivated = new AtomicBoolean();
		CountDownLatch startParentPrepare = new CountDownLatch(1);
		CountDownLatch parentPrepared = new CountDownLatch(1);
		CountDownLatch releaseParent = new CountDownLatch(1);
		terminal.onNullOwnerQuery = thread -> {
			if (thread == autoFlushThread.get()) {
				int query = autoFlushOwnerQueries.incrementAndGet();
				if (query == 2 && hookActivated.compareAndSet(false, true)) {
					hookQuery.set(query);
					startParentPrepare.countDown();
					await(parentPrepared, "ancestor prepared sink during owner resolution");
				}
			}
		};

		ExecutorService executor = Executors.newFixedThreadPool(2);
		Future<?> parentTask = executor.submit(() -> {
			await(startParentPrepare, "owner-resolution hook");
			try (SailSink sink = parent.sink(IsolationLevels.SERIALIZABLE)) {
				sink.prepare();
				parentPrepared.countDown();
				await(releaseParent, "ancestor preparation release");
			}
		});
		Future<?> autoFlushTask = executor.submit(() -> {
			autoFlushThread.set(Thread.currentThread());
			child.autoFlush();
		});
		boolean returnedBeforeRelease = false;
		boolean queuedRowVisible = false;
		Throwable autoFlushFailure = null;
		try {
			try {
				autoFlushTask.get(2, TimeUnit.SECONDS);
				returnedBeforeRelease = releaseParent.getCount() == 1;
			} catch (java.util.concurrent.TimeoutException blockedByAncestor) {
				// Release the held sink in finally before reporting the liveness failure.
			} catch (java.util.concurrent.ExecutionException failure) {
				autoFlushFailure = failure.getCause();
			}
		} finally {
			startParentPrepare.countDown();
			releaseParent.countDown();
			parentTask.get(5, TimeUnit.SECONDS);
			try {
				autoFlushTask.get(5, TimeUnit.SECONDS);
			} catch (java.util.concurrent.ExecutionException failure) {
				if (autoFlushFailure == null) {
					autoFlushFailure = failure.getCause();
				}
			}
			try (SailDataset dataset = child.dataset(IsolationLevels.NONE)) {
				queuedRowVisible = readAll(dataset.getStatements(null, null, null)).contains(queued);
			}
			child.close();
			parent.close();
			executor.shutdownNow();
			executor.awaitTermination(5, TimeUnit.SECONDS);
		}

		assertThat(hookActivated).as("the autoFlush thread reached the second null-owner query").isTrue();
		assertThat(hookQuery).hasValue(2);
		assertThat(parentPrepared.getCount()).as("the hook prepared the parent through the public sink API").isZero();
		assertThat(returnedBeforeRelease).as("child autoFlush returned while the parent sink was still prepared")
				.isTrue();
		assertThat(queuedRowVisible).as("the real buffered child row remains visible").isTrue();
		assertThat(autoFlushFailure).isNull();
	}

